INSERT INTO gps_jurisdiction_profile (jurisdiction, offer_key, service_class, source, source_url, entered_by, review_by, note) SELECT $LCXQ$united kingdom$LCXQ$, $LCXQ$marketing_activation$LCXQ$, $LCXQ$prohibited$LCXQ$, $LCXQ$System proposal, UNVERIFIED (assistant knowledge, cutoff 2026-01): FSMA s21 financial-promotion regime extends to cryptoassets (from 2023-10): promotions to UK audiences need an authorised approver, which LCX is not. Verify with qualified counsel before relying on this position.$LCXQ$, NULL, $LCXQ$nik$LCXQ$, $LCXQ$2027-03-01T07:58:04.850Z$LCXQ$, $LCXQ$Prohibited as sold: LCX cannot lawfully run promotion activation aimed at UK audiences without an FCA-authorised approver. A UK client marketing EXCLUSIVELY outside the UK is a different engagement — re-enter that as counsel_required with counsel sign-off.$LCXQ$ WHERE NOT EXISTS (SELECT 1 FROM gps_jurisdiction_profile WHERE jurisdiction = $LCXQ$united kingdom$LCXQ$ AND offer_key = $LCXQ$marketing_activation$LCXQ$);
