INSERT INTO gps_jurisdiction_profile (jurisdiction, offer_key, service_class, source, source_url, entered_by, review_by, note) SELECT $LCXQ$us$LCXQ$, $LCXQ$marketing_activation$LCXQ$, $LCXQ$prohibited$LCXQ$, $LCXQ$System proposal, UNVERIFIED (assistant knowledge, cutoff 2026-01): Securities solicitation risk and state-level regimes make promotion activation for US audiences undeliverable by LCX; the MiCA paper for a US project entering the EU is EU-facing work and fine. Verify with qualified counsel before relying on this position.$LCXQ$, NULL, $LCXQ$nik$LCXQ$, $LCXQ$2027-03-01T07:58:04.850Z$LCXQ$, $LCXQ$Prohibited as sold: activation aimed at US persons carries solicitation risk LCX cannot underwrite. US-client engagements marketing exclusively into the EEA are a different engagement — re-enter as counsel_required.$LCXQ$ WHERE NOT EXISTS (SELECT 1 FROM gps_jurisdiction_profile WHERE jurisdiction = $LCXQ$us$LCXQ$ AND offer_key = $LCXQ$marketing_activation$LCXQ$);

-- pricing_policy: append (the ordering IS the state)
INSERT INTO gps_pricing_policy (target_margin_pct, p_loss_ceiling, rationale, decided_by) VALUES (0.45, 0.1, $LCXQ$A 45% target median margin carries the three-stage waterfall’s coordination overhead and the unbilled owner time every engagement absorbs; below ~35% a single pessimistic-tail engagement erases its neighbour’s profit. The 0.10 loss ceiling sits at HALF the issue guard’s stated block threshold (maxPLoss 0.2), so system-proposed prices live safely inside the veto rather than testing it.$LCXQ$, $LCXQ$nik$LCXQ$);

-- the six standing decisions (append-only; DISTINCT ON (kind) latest wins everywhere they are read)
INSERT INTO gps_packet_decision (packet_kind, decision, final_proposal, apply_state, apply_detail, decided_by, notes) VALUES ($LCXQ$price_bands$LCXQ$, $LCXQ$approved$LCXQ$, $LCXQ${"kind":"price_bands","rows":[{"offerKey":"diagnostic","lowCents":250000,"midCents":400000,"highCents":600000,"currency":"USD","rationale":"Priced as a paid wedge, not a profit centre: low enough to say yes to inside one call, high enough that the reader takes its findings seriously. Placeholder was $1.5k–3k; consultancy quick-scan work commonly lands $2.5k–6k."},{"offerKey":"mica_whitepaper","lowCents":1500000,"midCents":2500000,"highCents":4000000,"currency":"USD","rationale":"EU law firms quote MiCA white-paper packages roughly €15k–50k+. LCX is not selling legal advice but drafting + submission craft with venue credibility, so mid sits at $25k — above the $12k–25k placeholder, below big-firm rates. High covers multi-token or contested-classification work."},{"offerKey":"legal_opinion_coordination","lowCents":1000000,"midCents":1500000,"highCents":2500000,"currency":"USD","rationale":"This is the COORDINATION fee only — scoping, counsel selection, fact package, review cycles. Counsel’s own fees pass through and are never inside this band; conflating them is how this offer loses money invisibly."},{"offerKey":"gtm_sprint","lowCents":1200000,"midCents":1800000,"highCents":3000000,"currency":"USD","rationale":"Two-to-three-week strategy sprints from boutique crypto advisories commonly land $10k–30k. Mid at $18k with the deliverable set the catalogue already defines."},{"offerKey":"marketing_activation","lowCents":1200000,"midCents":2000000,"highCents":3500000,"currency":"USD","rationale":"One activation programme, not a retainer. Agency equivalents run $10k–35k+ depending on channels; the perimeter packet constrains WHERE this may be sold at all, which matters more than the price."}]}$LCXQ$::jsonb, $LCXQ$applied$LCXQ$, $LCXQ$5 price band(s) written; every quote now opens on these numbers, attributed to nik.$LCXQ$, $LCXQ$nik$LCXQ$, $LCXQ$Approved by the owner in chat on 2026-08-31 and applied via this owner-run SQL file: the six UI approvals pre-dated his GPS access grant and never landed (gps_packet_decision was empty — verified by SELECT). Perimeter inserts are guarded, so any pre-existing hand-entered position was left untouched.$LCXQ$);
INSERT INTO gps_packet_decision (packet_kind, decision, final_proposal, apply_state, apply_detail, decided_by, notes) VALUES ($LCXQ$effort_triples$LCXQ$, $LCXQ$approved$LCXQ$, $LCXQ${"kind":"effort_triples","rows":[{"offerKey":"diagnostic","optimisticDays":1.5,"likelyDays":2.5,"pessimisticDays":4,"waterfall":{"aiDraftDays":0.5,"internalQaDays":1,"partnerDays":1},"rationale":"Template-driven report; AI drafts the structure from intake facts in half a day, one QA day, one partner-review day where the findings touch regulated ground."},{"offerKey":"mica_whitepaper","optimisticDays":6,"likelyDays":9,"pessimisticDays":14,"waterfall":{"aiDraftDays":2,"internalQaDays":4,"partnerDays":3},"rationale":"Annex I/II structure is templatable; the days live in QA against the actual token facts and the partner pass on classification language. Pessimistic covers a contested classification or a second review cycle with the venue."},{"offerKey":"legal_opinion_coordination","optimisticDays":3,"likelyDays":5,"pessimisticDays":8,"waterfall":{"aiDraftDays":1,"internalQaDays":2,"partnerDays":2},"rationale":"Coordination is fact-package assembly + counsel management. Partner days here are the LIAISON share, not the opinion itself — that is counsel’s own engagement, outside this triple."},{"offerKey":"gtm_sprint","optimisticDays":4,"likelyDays":6,"pessimisticDays":10,"waterfall":{"aiDraftDays":1.5,"internalQaDays":3,"partnerDays":1.5},"rationale":"Sprint structure is repeatable; QA carries the strategy judgment. Pessimistic covers a pivot mid-sprint."},{"offerKey":"marketing_activation","optimisticDays":5,"likelyDays":8,"pessimisticDays":13,"waterfall":{"aiDraftDays":2,"internalQaDays":3.5,"partnerDays":2.5},"rationale":"Activation needs channel execution (partner/agency share) plus compliance-gated copy, which the marketing module already enforces on LCX’s own mouth."}]}$LCXQ$::jsonb, $LCXQ$applied$LCXQ$, $LCXQ$5 effort triple(s) written; underwriting moves off basis:prior for new quotes.$LCXQ$, $LCXQ$nik$LCXQ$, $LCXQ$Approved by the owner in chat on 2026-08-31 and applied via this owner-run SQL file: the six UI approvals pre-dated his GPS access grant and never landed (gps_packet_decision was empty — verified by SELECT). Perimeter inserts are guarded, so any pre-existing hand-entered position was left untouched.$LCXQ$);
INSERT INTO gps_packet_decision (packet_kind, decision, final_proposal, apply_state, apply_detail, decided_by, notes) VALUES ($LCXQ$rate_cards$LCXQ$, $LCXQ$approved$LCXQ$, $LCXQ${"kind":"rate_cards","rows":[{"offerKey":"diagnostic","partnerClass":"analyst_support","unit":"per_day","proposedRateCents":60000,"expectedUnits":1,"rationale":"One analyst day at $600 for the partner-review share of the diagnostic."},{"offerKey":"mica_whitepaper","partnerClass":"regulatory_drafting_support","unit":"per_day","proposedRateCents":120000,"expectedUnits":3,"rationale":"Three days at $1,200 for classification-language review — support drafting rates, not partner-track counsel rates."},{"offerKey":"legal_opinion_coordination","partnerClass":"licensed_local_counsel_liaison","unit":"per_day","proposedRateCents":200000,"expectedUnits":2,"rationale":"Two liaison days at $2,000. Counsel’s OPINION fee is the client’s own engagement with counsel and never enters this card."},{"offerKey":"gtm_sprint","partnerClass":"gtm_specialist","unit":"per_day","proposedRateCents":100000,"expectedUnits":1.5,"rationale":"A day and a half of specialist input at $1,000/day on the sprint’s market-structure judgments."},{"offerKey":"marketing_activation","partnerClass":"activation_agency","unit":"fixed","proposedRateCents":400000,"expectedUnits":1,"rationale":"Fixed $4,000 agency execution block per activation, channels per the engagement."}],"applyDeferredReason":"PARTNER_BENCH is empty (D5) and gpsInputs refuses cards for unnamed partners — inventing a plausible counsel name to make this applicable would be the worst thing this packet could do."}$LCXQ$::jsonb, $LCXQ$recorded_only$LCXQ$, $LCXQ$Values recorded, nothing written to gps_rate_card: a card needs a NAMED partner and the bench is empty by decision D5. Name a partner in the registry and these values are one prefilled write away.$LCXQ$, $LCXQ$nik$LCXQ$, $LCXQ$Approved by the owner in chat on 2026-08-31 and applied via this owner-run SQL file: the six UI approvals pre-dated his GPS access grant and never landed (gps_packet_decision was empty — verified by SELECT). Perimeter inserts are guarded, so any pre-existing hand-entered position was left untouched.$LCXQ$);
