INSERT INTO gps_packet_decision (packet_kind, decision, final_proposal, apply_state, apply_detail, decided_by, notes) VALUES ($LCXQ$dpo_memo$LCXQ$, $LCXQ$approved$LCXQ$, $LCXQ${"kind":"dpo_memo","memo":{"question":"When a client (or their counsel) hands LCX third-party confidential material for a GPS engagement — and when the G4 portal lets them upload it — is LCX a controller or a processor for that material, and on what terms may it be accepted?","memoMarkdown":"## The question, precisely\nGPS delivery work runs on client-supplied material: token documentation, cap tables, legal memos, counterparty contracts. Some of it is confidential to THIRD parties (investors, counterparties, counsel work-product), and some contains personal data. Today the intake lockout refuses every upload surface because this question was never answered. The G4 portal cannot ship without an answer.\n\n## Roles analysis\n**For client-supplied engagement material: LCX is a processor.** The client determines the purpose (obtain the service) and the means (which documents to supply); LCX processes them solely on the client’s instruction to deliver the contracted work. That is the Article 28 shape, and it wants a Data Processing Agreement: documented instructions, confidentiality, security measures, sub-processor disclosure (Supabase — infrastructure already in eu-central-1, a repo-measured fact), deletion on termination.\n**For LCX’s own engagement records — quotes, margins, outcomes, perimeter stamps — LCX is the controller.** These exist for LCX’s own purposes (running its book) and no DPA covers them; the record distinguishes the two planes rather than blending them.\n**Third-party confidential material (not personal data) is a contract question, not a GDPR one:** the engagement terms need a confidentiality clause with a use-limitation matching the DPA’s instruction-limitation, so both planes point the same way.\n\n## Transfers and residence\nStorage is Supabase eu-central-1 (measured from this repository’s connection target, not assumed). While processing stays in the EEA no transfer mechanism is engaged; if a sub-processor outside the EEA is ever added, SCCs become the mechanism and the DPA’s sub-processor clause is where the client learns of it.\n\n## Retention\nProposal: client-supplied material is retained for the engagement plus 24 months (dispute horizon), then deleted; LCX’s own records are retained indefinitely as controller. The portal states both plainly.\n\n## The options\nOption A — adopt the processor posture with a DPA template (recommended): unlocks uploads and the portal with the strongest client story. Option B — controller-only: never accept client files; the portal ships forms-only and delivery keeps working from typed facts and external references. Option C — refuse uploads indefinitely: today’s posture, made permanent.","options":[{"id":"adopt_processor_dpa","label":"Processor posture + DPA template (recommended)","consequence":"Unlocks the G4 portal’s upload surface and the delivery desk’s client-material intake, behind a DPA the client accepts at engagement start. LCX commits to instruction-limited use, EEA residence, and deletion at engagement + 24 months."},{"id":"controller_only_no_uploads","label":"Controller-only: forms, never files","consequence":"The portal ships with typed intake forms only. Delivery continues to reference external material by location (the inert external_location field), and the intake lockout stays enforced everywhere."},{"id":"refuse_uploads_indefinitely","label":"Refuse uploads indefinitely","consequence":"Today’s posture becomes the decided one. G4 narrows to status + approvals only. Honest, and the most limiting for delivery volume."}],"recommendedOptionId":"adopt_processor_dpa"}}$LCXQ$::jsonb, $LCXQ$recorded_only$LCXQ$, $LCXQ$DPO decision recorded (option as approved: see final_proposal.memo.recommendedOptionId = adopt_processor_dpa). No surface changes today: G4 reads this decision and ships exactly what it permits.$LCXQ$, $LCXQ$nik$LCXQ$, $LCXQ$Approved by the owner in chat on 2026-08-31 and applied via this owner-run SQL file: the six UI approvals pre-dated his GPS access grant and never landed (gps_packet_decision was empty — verified by SELECT). Perimeter inserts are guarded, so any pre-existing hand-entered position was left untouched.$LCXQ$);
INSERT INTO gps_packet_decision (packet_kind, decision, final_proposal, apply_state, apply_detail, decided_by, notes) VALUES ($LCXQ$pricing_policy$LCXQ$, $LCXQ$approved$LCXQ$, $LCXQ${"kind":"pricing_policy","policy":{"targetMarginPct":0.45,"pLossCeiling":0.1},"rationale":"A 45% target median margin carries the three-stage waterfall’s coordination overhead and the unbilled owner time every engagement absorbs; below ~35% a single pessimistic-tail engagement erases its neighbour’s profit. The 0.10 loss ceiling sits at HALF the issue guard’s stated block threshold (maxPLoss 0.2), so system-proposed prices live safely inside the veto rather than testing it."}$LCXQ$::jsonb, $LCXQ$applied$LCXQ$, $LCXQ$Pricing policy appended (target margin 45% at the median, loss ceiling 0.1), decided by nik. propose-price answers from this row; every proposed price remains yours to edit, and the issue guard keeps its veto.$LCXQ$, $LCXQ$nik$LCXQ$, $LCXQ$Approved by the owner in chat on 2026-08-31 and applied via this owner-run SQL file: the six UI approvals pre-dated his GPS access grant and never landed (gps_packet_decision was empty — verified by SELECT). Perimeter inserts are guarded, so any pre-existing hand-entered position was left untouched.$LCXQ$);

COMMIT;

-- Verification — the whole register in one table. Expected: 6 packet rows, 5 bands, 5 triples,
-- 30 perimeter positions (fewer inserted-now if some pre-existed), 1 pricing policy row.
SELECT * FROM (
  SELECT '1 · packets decided' AS item, count(*)::text || ' of 6' AS detail FROM (SELECT DISTINCT packet_kind FROM gps_packet_decision) x
  UNION ALL SELECT '2 · price bands', count(*)::text || ' of 5' FROM gps_price_band
  UNION ALL SELECT '3 · effort triples', count(*)::text || ' of 5' FROM gps_effort_triple
  UNION ALL SELECT '4 · perimeter positions', count(*)::text || ' (expected 30)' FROM gps_jurisdiction_profile
  UNION ALL SELECT '5 · pricing policy rows', count(*)::text || ' (expected 1)' FROM gps_pricing_policy
  UNION ALL SELECT '6 · partners (still yours)', count(*)::text || ' (expected 0 until you name one)' FROM gps_partner_registry
) t ORDER BY item;
